-- Apply manually (dev, test, staging, then prod). Works on MariaDB 11.8 and MySQL 8.0. Run with the utf8mb4 client charset, e.g.: mariadb --default-character-set=utf8mb4 ...
-- IDEMPOTENT and edit-preserving: every UPDATE matches the row only while subject AND body still equal the OLD seed text, so templates edited by users are left alone; a second run matches nothing.
-- Requires email_templates (20261014_dunning.sql). The application works without this script (built-in defaults in EmailTemplateDefaults.cs already carry the new wording; only rows still holding the old seed text show the old wording).
-- Verify afterwards: SELECT code, language, subject FROM email_templates ORDER BY code, language;
SET NAMES utf8mb4;

UPDATE email_templates SET subject = 'PVM sąskaita faktūra {{InvoiceNumber}}', body_html = '<p>Gerbiamieji,</p><p>siunčiame sąskaitą faktūrą <strong>{{InvoiceNumber}}</strong> ({{InvoiceDate}}) už {{Total}}. Apmokėjimo terminas – {{DueDate}}.</p><p>Sąskaita pridėta PDF formatu.</p>{{CompanySignature}}'
 WHERE code = 'INVOICE_SEND' AND language = 'LT' AND subject = 'Sąskaita faktūra {{InvoiceNumber}}' AND body_html = '<p>Gerb. {{PartnerName}},</p><p>siunčiame sąskaitą faktūrą <strong>{{InvoiceNumber}}</strong> ({{InvoiceDate}}) už {{Total}}. Apmokėjimo terminas – {{DueDate}}.</p><p>Sąskaita pridėta PDF formatu.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Invoice {{InvoiceNumber}}', body_html = '<p>Dear {{PartnerName}},</p><p>Please find attached invoice <strong>{{InvoiceNumber}}</strong> dated {{InvoiceDate}} for {{Total}}. The payment due date is {{DueDate}}.</p>{{CompanySignature}}'
 WHERE code = 'INVOICE_SEND' AND language = 'EN' AND subject = 'Invoice {{InvoiceNumber}}' AND body_html = '<p>Dear {{PartnerName}},</p><p>please find attached invoice <strong>{{InvoiceNumber}}</strong> dated {{InvoiceDate}} for {{Total}}. The payment due date is {{DueDate}}.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Kreditinė sąskaita {{InvoiceNumber}}', body_html = '<p>Gerbiamieji,</p><p>siunčiame kreditinę sąskaitą <strong>{{InvoiceNumber}}</strong> ({{InvoiceDate}}) už {{Total}}.</p><p>Dokumentas pridėtas PDF formatu.</p>{{CompanySignature}}'
 WHERE code = 'CREDIT_NOTE_SEND' AND language = 'LT' AND subject = 'Kreditinė sąskaita {{InvoiceNumber}}' AND body_html = '<p>Gerb. {{PartnerName}},</p><p>siunčiame kreditinę sąskaitą <strong>{{InvoiceNumber}}</strong> ({{InvoiceDate}}) už {{Total}}.</p><p>Dokumentas pridėtas PDF formatu.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Credit note {{InvoiceNumber}}', body_html = '<p>Dear {{PartnerName}},</p><p>Please find attached credit note <strong>{{InvoiceNumber}}</strong> dated {{InvoiceDate}} for {{Total}}.</p>{{CompanySignature}}'
 WHERE code = 'CREDIT_NOTE_SEND' AND language = 'EN' AND subject = 'Credit note {{InvoiceNumber}}' AND body_html = '<p>Dear {{PartnerName}},</p><p>please find attached credit note <strong>{{InvoiceNumber}}</strong> dated {{InvoiceDate}} for {{Total}}.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = '{{ReportName}} {{Period}}', body_html = '<p>Gerbiamieji,</p><p>siunčiame ataskaitą „{{ReportName}}“ ({{Period}}).</p><p>Ataskaita pridėta prie šio laiško.</p>{{CompanySignature}}'
 WHERE code = 'REPORT_SEND' AND language = 'LT' AND subject = '{{ReportName}} {{Period}}' AND body_html = '<p>Gerb. {{PartnerName}},</p><p>siunčiame ataskaitą „{{ReportName}}“ ({{Period}}).</p><p>Ataskaita pridėta prie šio laiško.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = '{{ReportName}} {{Period}}', body_html = '<p>Dear {{PartnerName}},</p><p>Please find attached the report “{{ReportName}}” ({{Period}}).</p>{{CompanySignature}}'
 WHERE code = 'REPORT_SEND' AND language = 'EN' AND subject = '{{ReportName}} {{Period}}' AND body_html = '<p>Dear {{PartnerName}},</p><p>please find attached the report “{{ReportName}}” ({{Period}}).</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Priminimas dėl neapmokėtų sąskaitų', body_html = '<p>Gerbiamieji,</p><p>primename, kad žemiau išvardytų sąskaitų apmokėjimo terminas jau suėjo. Jei apmokėjimą jau atlikote, prašome šio laiško nepaisyti.</p>{{InvoiceTable}}<p>Iš viso pradelsta: <strong>{{TotalOverdue}}</strong>.</p><p>Jei turite klausimų, mielai padėsime.</p>{{CompanySignature}}'
 WHERE code = 'DUNNING_L1' AND language = 'LT' AND subject = 'Priminimas dėl neapmokėtų sąskaitų' AND body_html = '<p>Gerb. {{PartnerName}},</p><p>primename, kad žemiau išvardytų sąskaitų apmokėjimo terminas jau suėjo. Jei apmokėjimą jau atlikote, prašome šio laiško nepaisyti.</p>{{InvoiceTable}}<p>Iš viso pradelsta: <strong>{{TotalOverdue}}</strong>.</p><p>Jei turite klausimų, mielai padėsime.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Reminder: overdue invoices', body_html = '<p>Dear {{PartnerName}},</p><p>This is a friendly reminder that the payment due date of the invoices listed below has passed. If you have already made the payment, please disregard this message.</p>{{InvoiceTable}}<p>Total overdue: <strong>{{TotalOverdue}}</strong>.</p><p>Please let us know if you have any questions.</p>{{CompanySignature}}'
 WHERE code = 'DUNNING_L1' AND language = 'EN' AND subject = 'Reminder: overdue invoices' AND body_html = '<p>Dear {{PartnerName}},</p><p>this is a friendly reminder that the payment due date of the invoices listed below has passed. If you have already made the payment, please disregard this message.</p>{{InvoiceTable}}<p>Total overdue: <strong>{{TotalOverdue}}</strong>.</p><p>Please let us know if you have any questions.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Antrasis priminimas dėl pradelstų sąskaitų', body_html = '<p>Gerbiamieji,</p><p>nepaisant ankstesnio priminimo, žemiau išvardytų sąskaitų apmokėjimo negavome.</p>{{InvoiceTable}}<p>Iš viso pradelsta: <strong>{{TotalOverdue}}</strong>.</p><p>Prašome apmokėti per 7 dienas arba informuoti mus apie galimas priežastis, trukdančias tai padaryti.</p>{{CompanySignature}}'
 WHERE code = 'DUNNING_L2' AND language = 'LT' AND subject = 'Antrasis priminimas dėl pradelstų sąskaitų' AND body_html = '<p>Gerb. {{PartnerName}},</p><p>nepaisant ankstesnio priminimo, žemiau išvardytų sąskaitų apmokėjimo negavome.</p>{{InvoiceTable}}<p>Iš viso pradelsta: <strong>{{TotalOverdue}}</strong>.</p><p>Prašome apmokėti per 7 dienas arba informuoti mus apie galimas priežastis, trukdančias tai padaryti.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Second reminder: overdue invoices', body_html = '<p>Dear {{PartnerName}},</p><p>Despite our previous reminder, we have not received payment for the invoices listed below.</p>{{InvoiceTable}}<p>Total overdue: <strong>{{TotalOverdue}}</strong>.</p><p>Please arrange payment within 7 days or let us know if anything prevents you from doing so.</p>{{CompanySignature}}'
 WHERE code = 'DUNNING_L2' AND language = 'EN' AND subject = 'Second reminder: overdue invoices' AND body_html = '<p>Dear {{PartnerName}},</p><p>despite our previous reminder, we have not received payment for the invoices listed below.</p>{{InvoiceTable}}<p>Total overdue: <strong>{{TotalOverdue}}</strong>.</p><p>Please arrange payment within 7 days or let us know if anything prevents you from doing so.</p>{{CompanySignature}}';

UPDATE email_templates SET subject = 'Paskutinis priminimas dėl pradelstų sąskaitų', body_html = '<p>Gerbiamieji,</p><p>tai paskutinis priminimas dėl žemiau išvardytų pradelstų sąskaitų.</p>{{InvoiceTable}}<p>Iš viso pradelsta: <strong>{{TotalOverdue}}</strong>.</p><p>Prašome sumokėti per 5 darbo dienas. Jei apmokėjimas jau atliktas arba yra neaiškumų dėl sąskaitų, prašome nedelsiant su mumis susisiekti.</p>{{InterestBlock}}{{CompanySignature}}'
 WHERE code = 'DUNNING_L3' AND language = 'LT' AND subject = 'Paskutinis priminimas dėl pradelstų sąskaitų' AND body_html = '<p>Gerb. {{PartnerName}},</p><p>tai paskutinis priminimas dėl žemiau išvardytų pradelstų sąskaitų.</p>{{InvoiceTable}}<p>Iš viso pradelsta: <strong>{{TotalOverdue}}</strong>.</p><p>Prašome sumokėti per 5 darbo dienas. Jei apmokėjimas jau atliktas arba yra neaiškumų dėl sąskaitų, prašome nedelsiant su mumis susisiekti.</p>{{InterestBlock}}{{CompanySignature}}';

UPDATE email_templates SET subject = 'Final reminder: overdue invoices', body_html = '<p>Dear {{PartnerName}},</p><p>This is our final reminder regarding the overdue invoices listed below.</p>{{InvoiceTable}}<p>Total overdue: <strong>{{TotalOverdue}}</strong>.</p><p>Please make the payment within 5 business days. If payment has already been made or anything about the invoices is unclear, please contact us right away.</p>{{InterestBlock}}{{CompanySignature}}'
 WHERE code = 'DUNNING_L3' AND language = 'EN' AND subject = 'Final reminder: overdue invoices' AND body_html = '<p>Dear {{PartnerName}},</p><p>this is our final reminder regarding the overdue invoices listed below.</p>{{InvoiceTable}}<p>Total overdue: <strong>{{TotalOverdue}}</strong>.</p><p>Please make the payment within 5 business days. If payment has already been made or anything about the invoices is unclear, please contact us right away.</p>{{InterestBlock}}{{CompanySignature}}';
